  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "Complete the authentic 45-minute uninterrupted circuit lab check as one indivisible block, with the required continuous 45-minute slot disclosed rather than split into shorter sessions."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "GENERAL",
          "outcome": "I need to complete a 45-minute uninterrupted authentic circuit lab check. Interrupting the measurement invalidates the check. Availability is only 30 minutes a day; disclose the conflict rather than silently turning it into a shorter check.",
          "explanation": "The accepted outcome is a single authentic lab check that must run continuously for 45 minutes. The supplied availability provides only 30-minute daily windows, so the honest educational plan must retain the full 45-minute indivisible task and disclose the schedule conflict instead of substituting a shorter or split check. No preparatory or invented exercise is added because the required capability is the authentic check itself, and the observed history shows no completed work or readiness evidence.",
          "recommendedEffort": {
            "lowMinutes": 45,
            "likelyMinutes": 45,
            "highMinutes": 45
          },
          "phases": [
            {
              "localId": "labcheck",
              "title": "Uninterrupted authentic lab check",
              "outcome": "Perform the full 45-minute circuit lab check in one continuous, uninterrupted sitting without invalidating the measurement.",
              "effort": {
                "lowMinutes": 45,
                "likelyMinutes": 45,
                "highMinutes": 45
              },
              "readinessCriterion": "The complete 45-minute circuit lab check is finished in a single uninterrupted block and the measurement is valid."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "The uninterrupted authentic lab check is the required capability and the only assessed outcome; it must be retained as one indivisible 45-minute task."
          }
        ],
        "activities": [
          {
            "localId": "circuit_lab_check",
            "outcomeRefs": [
              "labcheck"
            ],
            "scopeRefs": [
              "scope_1"
            ],
            "title": "Complete the 45-minute uninterrupted circuit lab check",
            "activityType": "Authentic laboratory check",
            "purpose": "Perform the required authentic circuit measurement as one continuous 45-minute block so the result is valid.",
            "instructions": "Set up the circuit lab check before starting the timer. Once you begin the 45-minute measurement, do not pause, split, or restart the session; any interruption invalidates the check. Complete the full 45 minutes in one sitting and record the measurement as specified by the lab. If only 30-minute daily windows are available, do not shorten or split the check: treat this as a scheduling conflict and arrange a continuous 45-minute slot before attempting it.",
            "completionCriterion": "The full 45-minute circuit lab check is completed in one uninterrupted block and the resulting measurement is valid.",
            "effort": {
              "lowMinutes": 45,
              "likelyMinutes": 45,
              "highMinutes": 45
            },
            "timeboxMinutes": 45,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": []
          }
        ],
        "decisions": {
          "assumptions": [],
          "tradeOffs": [
            "The required 45-minute uninterrupted check cannot fit inside the supplied 30-minute daily availability; the plan retains the honest indivisible duration and discloses the conflict rather than replacing it with a shorter check."
