          "unresolvedUncertainty": [
            "The supplied availability does not show a continuous 45-minute window, so the allocator may report a placement conflict."
          ],
          "stoppingConditions": [
            "Stop when the full 45-minute uninterrupted circuit lab check has been completed and the measurement is valid."
          ]
        }
      }
    }
