              "lowMinutes": 25,
              "likelyMinutes": 30,
              "highMinutes": 45
            },
            "timeboxMinutes": 30,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [],
            "stoppingCondition": "Stop after the five items have been attempted, checked and marked; do not add extra circuits at this stage.",
